on conflict(id) do update set question_text=excluded.question_text,category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,option_a=excluded.option_a,option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,correct_answer=excluded.correct_answer,explanation=excluded.explanation,estimated_time_seconds=excluded.estimated_time_seconds,active=true;
