('db-1-1','Which clause filters rows before grouping?','database_technical','SQL Filtering',9.4,'WHERE','HAVING','ORDER BY','DISTINCT','A','WHERE filters input rows; HAVING filters groups.',60,true),
('db-1-2','Which clause filters aggregate groups?','database_technical','Aggregation',9.5,'HAVING','WHERE','SELECT DISTINCT','LIMIT','A','HAVING is evaluated on groups after GROUP BY.',60,true),
('db-1-3','What property must every primary-key value have?','database_technical','Keys',9,'It is unique and non-null','It may repeat','It must be text','It must reference another table','A','A primary key uniquely identifies a row and cannot be null.',60,true),
('db-1-4','What does a foreign key primarily enforce?','database_technical','Foreign Keys',9.1,'Referential integrity','Sort order','Column encryption','Query caching','A','It constrains values to referenced candidate-key values.',60,true),
('db-1-5','Which normal form removes partial dependency on a composite key?','database_technical','Normalization',9.2,'Second normal form','First normal form','Third normal form','BCNF only','A','2NF removes partial dependencies on a candidate key.',60,true),
('db-1-6','Which ACID property ensures committed data survives failure?','database_technical','Transactions',9.3,'Durability','Atomicity','Isolation','Consistency','A','Durability preserves committed changes.',60,true),
('db-1-7','Which ACID property makes a transaction all-or-nothing?','database_technical','Transactions',9.4,'Atomicity','Isolation','Durability','Availability','A','Atomicity prevents partial transactions.',60,true),
('db-1-8','What is the usual trade-off of adding an index?','database_technical','Indexes',9.5,'Faster reads but extra storage and write cost','Faster writes with no cost','Automatic normalization','Guaranteed uniqueness for every index','A','Indexes accelerate matching reads but must be maintained on writes.',60,true),
('db-1-9','Which join retains every row from the left table?','database_technical','JOIN',9,'LEFT JOIN','INNER JOIN','CROSS JOIN','SELF JOIN','A','LEFT JOIN preserves all left rows.',60,true),
('db-1-10','Which predicate correctly tests missing SQL values?','database_technical','NULL',9.1,'IS NULL','= NULL','== NULL','NULL()','A','NULL uses IS NULL because equality with NULL is unknown.',60,true),
('db-1-11','A query selects department and COUNT(*). What else is normally required?','database_technical','Grouping',9.2,'GROUP BY department','ORDER BY department','HAVING department','DISTINCT COUNT','A','Non-aggregated selected columns normally belong in GROUP BY.',60,true),
('db-1-12','What anomaly is prevented when a transaction cannot read uncommitted changes?','database_technical','Isolation',9.3,'Dirty read','Lost index','Dead column','Schema drift','A','Dirty reads observe another transaction''s uncommitted work.',60,true),
('db-1-13','COUNT(column_name) differs from COUNT(*) because it does what?','database_technical','Query Logic',9.4,'Ignores NULL values in that column','Counts distinct values only','Counts tables','Returns text','A','COUNT(column) ignores NULL; COUNT(*) counts rows.',60,true),
('db-1-14','What does UNION do by default?','database_technical','Set Operations',9.5,'Removes duplicate rows','Keeps all duplicates','Joins columns by keys','Updates both queries','A','UNION applies duplicate elimination; UNION ALL does not.',60,true),
('db-1-15','A correlated subquery is evaluated with reference to what?','database_technical','Subqueries',9,'A row from the outer query','Only system tables','A stored procedure','An index page','A','It references values supplied by the outer query.',60,true),
('db-1-16','Which constraint limits values using a Boolean condition?','database_technical','Constraints',9.1,'CHECK','DEFAULT','INDEX','VIEW','A','CHECK validates a predicate for inserted or updated rows.',60,true),
('db-1-17','A standard database view primarily stores what?','database_technical','Views',9.2,'A query definition','A copy of every result row','An index only','Transaction logs','A','A normal view stores its defining query, unlike a materialized view.',60,true),
('db-1-18','A transitive dependency of a non-key attribute violates which normal form?','database_technical','Normalization',9.3,'Third normal form','First normal form','Second normal form only','Domain-key normal form only','A','3NF removes transitive dependencies on candidate keys.',60,true),
('db-1-19','What does an INNER JOIN return?','database_technical','Joins',9.4,'Rows satisfying the join condition in both inputs','Every left row','Every possible pair only','Only unmatched rows','A','INNER JOIN retains matching combinations.',60,true),
